#include "short.h"

size_t short_encode(uint64_t n, char *out) {
  char tmp[SHORT_CODE_MAX];
  size_t len = 0;
  do {
    tmp[len++] = SHORT_ALPHABET[n % 62];
    n /= 62;
  } while (n > 0);
  for (size_t i = 0; i < len; i++) out[i] = tmp[len - 1 - i];
  out[len] = '\0';
  return len;
}
